   551  void Flow::processDetectedProtocolData() {
   552    u_int16_t l7proto;
   553    Host *cli_h = NULL, *srv_h = NULL;
   554    /*
   555      Make sure to actual client and server to avoid setting wrong names (e.g.,
   556      set the server name to the client)
   557      https://github.com/ntop/ntopng/issues/5506
   558     */
   559    get_actual_peers(&cli_h, &srv_h);
   560
   561    if (ndpiFlow == NULL) return;
   562
   563    l7proto = ndpi_get_lower_proto(ndpiDetectedProtocol);
   564
   565    if ((l7proto != NDPI_PROTOCOL_DNS) &&
   566        (l7proto != NDPI_PROTOCOL_DHCP) /* host_server_name in DHCP is for the
   567                                           client name, not the server */
   568        && (ndpiFlow->host_server_name[0] != '\0') && (!host_server_name)) {
   569      Utils::sanitizeHostName((char *)ndpiFlow->host_server_name);
   570
   571      if (ndpi_is_proto(ndpiDetectedProtocol, NDPI_PROTOCOL_HTTP)) {
   572        char *double_column = strrchr((char *)ndpiFlow->host_server_name, ':');
   573
   574        if (double_column) double_column[0] = '\0';
   575      }
   576
   577      /*
   578        Host server name equals the Host: HTTP header field.
   579      */
   580      host_server_name = strdup((char *)ndpiFlow->host_server_name);
   581    }
   582
   583    switch (l7proto) {
   584      case NDPI_PROTOCOL_BITTORRENT:
   585        if (!bt_hash) setBittorrentHash((char *)ndpiFlow->protos.bittorrent.hash);
   586        break;
   587
   588      case NDPI_PROTOCOL_MDNS:
   589        /* protos.mdns.{answer,name} already propagated to hosts in
   590         * Flow::hosts_periodic_stats_update  */
   591        break;
   592
   593      case NDPI_PROTOCOL_TOR:
   594      case NDPI_PROTOCOL_TLS:
   595      case NDPI_PROTOCOL_QUIC:
   596        if (ndpiFlow->host_server_name[0] != '\0') {
   597          if (ndpiDetectedProtocol.app_protocol != NDPI_PROTOCOL_DOH_DOT &&
   598              cli_h && cli_h->isLocalHost())
   599            cli_h->incrVisitedWebSite(ndpiFlow->host_server_name);
   600
   601          if (cli_h) cli_h->incContactedService(ndpiFlow->host_server_name);
   602  #if 0
   603          /*
   604            Commented out as it will be eventually set below by (***)
   605            This should prevent misclassifying host names
   606          */
   607          if (srv_h) srv_h->setServerName(host_server_name);
   608  #endif
   609        }
   610        break;
   611
   612      case NDPI_PROTOCOL_HTTP:
   613      case NDPI_PROTOCOL_HTTP_PROXY:
   614        if (ndpiFlow->http.url) {
   615          if (!protos.http.last_url)
   616            protos.http.last_url = strdup(ndpiFlow->http.url);
   617
   618          if ((!protos.http.last_user_agent) && ndpiFlow->http.user_agent)
   619            protos.http.last_user_agent = strdup(ndpiFlow->http.user_agent);
   620
   621          setHTTPMethod(ndpiFlow->http.method);
   622        }
   623
   624        break;
   625    } /* switch */
   626  }
